        s += `<span class="color"><i class="swatch" style="background:${hex}"></i>${esc}</span>`;
      } else if (cls) {
        s += `<span class="${cls}">${esc}</span>`;
      } else {
        s += esc;
      }
    }
    html.push(s);
  }
  return html.join('\n');
